        [S("Standard error", math=r"3/\sqrt{36} = 0.5"), S("Margin of error", math=r"1.96 \times 0.5 = 0.98"), S("Interval", math=r"20 \pm 0.98 = (19.02,\ 20.98)")],
        "Confidence interval for a mean", "Calculation", "First find the standard error, then multiply by 1.96.",
